from flask import Flask, jsonify, request
import socket

app = Flask(__name__)

# Dictionary to store the screensharing URLs
screensharing_urls = {}

@app.route('/screenshare', methods=['POST'])
def create_screenshare():
    url = request.get_json()['url']
    if url not in screensharing_urls:
        # Create a new socket
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.bind(('localhost', 8080))
        sock.listen(1)

        # Add the socket to the dictionary with the URL as the key
        screensharing_urls[url] = {'sock': sock, 'clients': []}

    # Return the URL as the response
    return jsonify({'url': url})

@app.route('/join_screenshare', methods=['GET'])
def join_screenshare():
    url = request.args.get('url')
    if url in screensharing_urls:
        # Connect to the socket
        sock = screensharing_urls[url]['sock']
        sock.accept()
        screensharing_urls[url]['clients'].append(request.remote_addr)
        return jsonify({'message': 'Joining successfully!'})
    else:
        return jsonify({'error': 'Invalid URL'}), 404

if __name__ == '__main__':
    app.run(debug=True)
```
